"""Deep merge of configuration dictionaries."""

from copy import deepcopy


def _prune(value):
    """Return an independent copy of ``value`` with None-valued dict keys removed."""
    if isinstance(value, dict):
        return {k: _prune(v) for k, v in value.items() if v is not None}
    return deepcopy(value)


def deep_merge(base: dict, override: dict) -> dict:
    """Return ``base`` with ``override`` merged on top of it.

    Dicts merge recursively; any other value (lists included) is replaced by
    the override. An override value of ``None`` removes the key. Inputs are not
    modified and the result shares no mutable objects with them.
    """
    result = {k: deepcopy(v) for k, v in base.items()}
    for key, value in override.items():
        if value is None:
            result.pop(key, None)
        elif isinstance(value, dict) and isinstance(base.get(key), dict):
            result[key] = deep_merge(base[key], value)
        else:
            result[key] = _prune(value)
    return result
